using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and linguistics." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds three patents in natural language processing.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Miller", Title = "Associate Professor of Mathematics", Bio = "Dr. Miller's research focuses on algebraic topology and its applications. He received the Distinguished Teaching Award in 2023.", Email = "j.miller@university.edu" },
            new() { Id = 3, Name = "Prof. Emily Watson", Title = "Professor of English", Bio = "Prof. Watson is an expert in Victorian literature and creative writing. She is the author of three novels and numerous critical essays.", Email = "e.watson@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Kim", Title = "Professor of Physics", Bio = "Dr. Kim conducts research in quantum mechanics and particle physics. He previously worked at CERN on the Large Hadron Collider project.", Email = "r.kim@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Garcia", Title = "Associate Professor of History", Bio = "Dr. Garcia specializes in Latin American history and postcolonial studies. Her book on revolutionary movements won the National History Prize.", Email = "m.garcia@university.edu" },
            new() { Id = 6, Name = "Dr. Alan Turing Jr.", Title = "Assistant Professor of Computer Science", Bio = "Dr. Turing focuses on cybersecurity and distributed systems. He brings industry experience from a decade at major tech companies.", Email = "a.turing@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 350", Title = "Computer Networks & Security", Description = "Covers network protocols, architecture, and security principles including encryption, authentication, and secure system design.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = false },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential and integral calculus. Topics include limits, derivatives, integrals, and the Fundamental Theorem of Calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 5, Code = "MATH 220", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 6, Code = "ENG 110", Title = "Academic Writing", Description = "Develops skills in academic essay writing, research methods, critical reading, and argumentation.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 7, Code = "ENG 250", Title = "British Literature Survey", Description = "A survey of major works of British literature from the medieval period through the 20th century, exploring themes of identity, power, and social change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Introduction to mechanics, thermodynamics, and waves. Includes laboratory sessions for hands-on experimentation.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from ancient times through the late medieval period, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 11, Code = "HIST 260", Title = "Modern Latin America", Description = "Explores the history of Latin America from independence movements to the present, examining political revolutions, economic development, and cultural identity.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

