@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Browse Courses</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search courses..."
                   @bind="_searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="_selectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @if (_courses.Any())
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in FilteredCourses)
                    {
                        <tr>
                            <td>@course.Code</td>
                            <td>@course.Title</td>
                            <td>@course.Department.Name</td>
                            <td>@course.Credits</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @FilteredCourses.Count course(s)</p>
    }
    else
    {
        <p class="text-muted">No courses found.</p>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> _courses = new();
    private List<Department> _departments = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private List<Course> FilteredCourses
    {
        get
        {
            var query = _courses.AsEnumerable();

            if (_selectedDepartmentId > 0)
                query = query.Where(c => c.DepartmentId == _selectedDepartmentId);

            if (!string.IsNullOrWhiteSpace(_searchTerm))
            {
                var term = _searchTerm;
                query = query.Where(c =>
                    c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            return query.ToList();
        }
    }

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _courses = CatalogService.GetCourses();

        if (DepartmentId.HasValue)
            _selectedDepartmentId = DepartmentId.Value;
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<div class="container mt-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted</h4>
            <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been submitted successfully. You will receive a confirmation via your university email.</p>
            <hr>
            <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        </div>
    }
    else
    {
        <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

        <form method="post" @onsubmit="HandleSubmit" @formname="enrollment">
            <AntiforgeryToken />

            <div class="row">
                <div class="col-md-6">
                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <input type="text" class="form-control" id="studentName" name="StudentName"
                               @bind="_model.StudentName" required />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <input type="text" class="form-control" id="studentId" name="StudentId"
                               @bind="_model.StudentId" required placeholder="e.g., STU-12345" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <select class="form-select" id="courseSelect" name="CourseId"
                                @bind="_model.CourseId" required>
                            <option value="0" disabled>Select a course...</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        </select>
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </div>
            </div>
        </form>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.StudentName) ||
            string.IsNullOrWhiteSpace(_model.StudentId) ||
            _model.CourseId == 0)
            return;

        var course = CatalogService.GetCourse(_model.CourseId);
        _selectedCourseTitle = course != null ? $"{course.Code} — {course.Title}" : "Unknown Course";

        CatalogService.SubmitEnrollmentRequest(_model);
        _submitted = true;
    }
}

